 bindAction('#continue-revision',async()=>{const cp=j.availableCheckpoints.find(c=>c.provenance?.kind==='visual-revision'&&c.completed===c.total);const n=await api('/api/jobs/'+j.id+'/continue-checkpoint',{checkpointId:cp.id});await refresh();showJob(n.id);});
