 bindAction('#preview',async()=>{await post(j,'preview');await refresh();});bindAction('#recapture-assess',async()=>{const n=await post(j,'recapture-assess');await refresh();showJob(n.id);});bindAction('#assess-current',async()=>{const n=await post(j,'assess-current');await refresh();showJob(n.id);});bindAction('#reevaluate',async()=>{await post(j,'reevaluate');await refresh();});bindAction('#cancel',async()=>{await post(j,'cancel');await refresh();});bindAction('#optimize-round',async()=>{const n=await post(j,'refine',{modelSettings:{model:state.budget.model,reasoningEffort:'xhigh'},optimization:{analysis:$('#optimization-analysis').value,hypothesis:$('#optimization-hypothesis').value}});await refresh();showJob(n.id);});bindAction('#spatial-refine',async()=>{const n=await post(j,'spatial-refine',{round:Number($('#spatial-basis').value),diagnosedStrategy:$('#spatial-diagnosed-strategy').value});await refresh();showJob(n.id);});bindAction('#diagnosed-refine',async()=>{const n=await post(j,'refine',{diagnosedStrategy:$('#diagnosed-strategy').value});await refresh();showJob(n.id);});bindAction('#refine-scene',async()=>{const n=await post(j,'refine',$('#refine-current-model')?.checked?{modelSettings:refinementSettings(j)}:{});await refresh();showJob(n.id);});bindAction('#align-scene',async()=>{const n=await post(j,'align');await refresh();showJob(n.id);});for(const action of ['retry','rebuild','continue-plan'])bindAction('#'+action,async()=>{const n=await post(j,action);await refresh();showJob(n.id);});
