function qualityHTML(j){return j.quality?(j.deliveryAssessment?.standard==='basic70'?'<p class="callout">70分基础交付：'+esc(statuses[j.deliveryAssessment.status])+'；80分完整规范：'+esc(statuses[j.strictStatus])+'。综合分 '+j.deliveryAssessment.score+'，原始加权分 '+j.deliveryAssessment.rawScore+'。</p><p class="hint">'+esc([...j.deliveryAssessment.reasons,...j.deliveryAssessment.warnings.map(x=>x.id+'：'+x.reason)].join('；'))+'</p>':'')+scoreComparisonHTML(j)+criteriaHTML(j)+'<p class="hint">评分标准 '+esc(j.quality.policy?.version??j.policy?.version??'历史记录')+' · 按本次任务保存的权重计算</p>'+j.quality.dimensions.map(d=>`<div class="score-row"><span>${esc(d.label)}</span><b>${d.points.toFixed(1)} / ${d.weight}</b></div><div class="bar"><i style="width:${d.score*20}%"></i></div>`).join('')+'<p class="hint">'+esc(j.quality.reasons.join('；'))+'</p>':'<p>还没有视觉评分。</p>';}
function specHTML(j){return `<p class="hint">规范版本 ${esc(j.specSource?.version||'历史记录')} · 脚本与视觉评估共同判定。</p><div class="table-wrap"><table><tr><th>条款</th><th>结果</th><th>依据</th></tr>${(j.spec?.rules||[]).map(r=>`<tr><td>${esc(r.id+' '+r.title)}</td><td>${r.kind==='preference'?'<span class="pill needs_review">'+(r.status==='passed'?'符合选样偏好':'选样建议')+'</span>':pill(r.status)}</td><td>${esc(r.reason)}<br>${r.frames?.map(f=>`<a href="${file(j,'runtime/'+f)}" target="_blank">${esc(f)}</a>`).join(' ')||''}</td></tr>`).join('')}</table></div>`;}
function stageBatchHTML(b){const r=b.stageResult,labels={passed:'阶段通过',failed:'阶段未达标',invalid:'证据不一致',in_progress:b.started?'评测中':'尚未开始'};return `<div class="card-heading"><h2>${esc(b.name)} · 十例阶段试验</h2><span class="pill ${r.status==='invalid'?'needs_review':r.status==='in_progress'?'running':r.status}">${labels[r.status]}</span></div><p>固定 ${esc(b.pipelineVersion.label)} · 每例一次提交，首稿加最多两轮自动修正；80 分与全部硬门槛。</p><div class="metrics"><div><b>${r.passed} / 10</b><span>单次提交内达标 · 目标至少 8 例</span></div><div><b>${(r.rate*100).toFixed(0)}%</b><span>${r.complete?'最终通过率':'当前通过占比 · 分母固定十例'}</span></div><div><b>${r.firstPass}</b><span>首稿直接通过</span></div></div><p class="hint">阶段结果用于检验有限迭代能力，不认证稳定 v1。手动恢复、重新提交、单独复评均不能补入本阶段成功率。</p>${r.errors.length?`<p class="callout">${esc(r.errors.join('；'))}</p>`:''}<table><thead><tr><th>案例与输入</th><th>状态</th><th>最终分数</th><th>实际结果</th></tr></thead><tbody>${r.cases.map(c=>{const input=b.cases.find(x=>x.id===c.id);return `<tr><td>${esc(c.id)}<br><small>${modes[input.mode]||'输入'} · ${esc(input.prompt?.slice(0,100)||'参考图片')}</small></td><td>${c.passed?'阶段达标':statuses[c.status]||'待提交'}${c.reasons.length?'<br><small>'+esc(c.reasons.join('；'))+'</small>':''}</td><td>${Number.isFinite(c.score)?c.score.toFixed(1):'—'}</td><td>${c.jobId?`<a href="#job/${esc(c.jobId)}">查看生成结果 →</a>`:'尚无生成结果'}</td></tr>`;}).join('')}</tbody></table>${!b.started&&b.current&&r.status!=='invalid'?`<button data-start="${b.id}" class="primary" ${!canCall(50)?'disabled':''}>开始十例阶段试验</button>`:''}<details><summary>冻结范围与正式认证</summary><p>${esc(b.stageValidation.noveltyScope)}</p><p>输入清单 ${esc(b.stageValidation.manifestSha256.slice(0,12))} · 每例提交上限 1 · 自动修正上限 2</p><p>正式认证仍要求评分器独立人工标定、三种输入每类至少30例、各模式通过率至少90%、总体95% Wilson下界至少80%，并覆盖三个复杂度。</p></details>`;}
function batchHTML(b){if(b.stageResult)return stageBatchHTML(b);const r=b.result;return `<div class="card-heading"><h2>${esc(b.name)}</h2>${pill(r.status)}</div><div class="metrics"><div><b>${r.passed} / ${r.n}</b><span>固定案例通过</span></div><div><b>${(r.rate*100).toFixed(1)}%</b><span>${r.complete?'最终成功率':'当前通过占比'}</span></div><div><b>${r.firstPass}</b><span>首稿通过</span></div></div><table><tr><th>输入方式</th><th>通过 / 总数</th><th>成功率</th></tr>${r.groups.map(g=>`<tr><td>${modes[g.mode]}</td><td>${g.passed} / ${g.n}</td><td>${(g.rate*100).toFixed(1)}%</td></tr>`).join('')}</table><p class="hint">${!b.current?'这是历史版本的评测记录。请为当前版本导入新的评测集。':r.complete?'结果仅适用于这组固定案例。':'评测尚未完成，当前数字不能作为成功率结论。'}</p>${!b.started&&b.current?`<button data-start="${b.id}" class="primary" ${!canCall(b.cases.length*3)?'disabled':''}>开始评测</button>`:''}<details><summary>版本、统计边界与待完成条件</summary><p class="hint">${esc(r.reasons.join('；'))}</p><p class="hint">版本 ${b.profile.id.slice(0,12)} · 95% 区间下界 ${(r.interval.lower*100).toFixed(1)}% · 每例最多 ${b.policy.maxAttempts} 次尝试</p></details>`;}
function bindStarts(){document.querySelectorAll('[data-start]').forEach(b=>b.onclick=async()=>{try{b.disabled=true;await api('/api/batches/'+b.dataset.start+'/start',{});await refresh();}catch(e){error(e);b.disabled=false;}});}
async function renderBench(){screen='bench';await refresh();selected=null;location.hash='bench';$('#breadcrumb').textContent='管线评测';clearError();const selectedProfile=benchProfile(),cal=benchCalibration(),eligible=state.jobs.filter(j=>terminal(j)&&(j._summary?j.benchEligible:j.runtime&&j.review)&&(j.assessmentProfileId??(j.assessmentProfile??j.profile).id)===selectedProfile.id).slice(0,60);$('#content').innerHTML=`<div class="intro compact"><div class="eyebrow">VALIDATE THE PIPELINE</div><h1>从单个成功，到稳定生成。</h1><p>先用十个新案例验证有限迭代，再以更大的样本集进行正式认证。</p></div><div class="metrics overview"><div><b>1. 十例阶段试验</b><span>一次提交内至少 8 / 10 达标</span></div><div><b>2. 独立评分标定</b><span>${cal?.result.status==='certified'?'独立人工标签已验证':'等待独立标签与评估证据'}</span></div><div><b>3. 正式认证</b><span>更大样本覆盖三种输入与三个复杂度</span></div></div><section class="card"><label>评测模型配置<select id="bench-profile">${(state.profiles||[state.profile]).map(p=>`<option value="${p.id}" ${p.id===selectedProfile.id?'selected':''}>${esc(p.model)} · ${esc(p.reasoningEffort||'默认')}</option>`).join('')}</select></label><p class="hint">不同模型或思考深度分别标定、统计，不混用通过率。</p><div class="card-heading"><h2>评分器标定</h2>${pill(cal?.result.status||'unverified')}</div><p>比较实际评分与独立人工标签，检查是否把不合格场景放行。</p><p class="hint">${esc(cal?.result.reasons.join('；')||'标定证据满足当前版本要求')}</p><div class="actions"><button id="calibration">查看标定样本</button><button id="prepare-calibration" ${eligible.length?'':'disabled'}>准备当前版本的复核样本（${eligible.length}）</button></div><p class="hint">准备样本只收集输入与实际画面，不会代填人工标签。正反样本各需 6 例；数量不足或标签未完成时继续保持“尚未认证”。</p></section>${state.batches.map(b=>`<section class="card" data-batch="${b.id}">${batchHTML(b)}</section>`).join('')}<section class="card"><h2>导入评测集</h2><label>评测用途<select id="batch-purpose"><option value="stage-80">十例阶段试验 · 至少 8 例达标</option><option value="certification">正式认证 · 多样本与独立标定</option></select></label><p id="batch-purpose-note">十个未参与调试的案例；每例一次提交、最多两轮自动修正；固定80分与全部硬门槛。此阶段不认证稳定版。</p><p>使用已准备好的案例文件。导入会冻结输入和当前管线版本，随后再启动评测。</p><input id="manifest-file" type="file" accept="application/json,.json" aria-label="评测集 JSON 文件"><div class="actions"><button id="freeze" class="primary" disabled>冻结评测集</button><span class="hint" id="manifest-info">请选择案例文件</span></div><details><summary>评测规则与高级导入</summary><p class="hint">阶段试验：十个新案例，每例一次提交、最多两轮自动视觉修正；全部完成后至少八例达标。正式认证：每种输入 ≥30 例，各模式 ≥90%，总体 95% Wilson 下界 ≥80%；每例最多两次独立提交，重试不增加样本数。两种统计均不把未通过、取消或待复核计为成功。模型格式纠正和局部修复会增加请求量。</p><textarea id="manifest" rows="5" placeholder='{"name":"留出集","cases":[{"id":"p01","prompt":"..."}]}'></textarea><button id="freeze-text">使用上面的 JSON 冻结</button></details></section>`;$('#bench-profile').onchange=()=>{benchProfileId=$('#bench-profile').value;renderBench();};$('#batch-purpose').onchange=()=>{$('#batch-purpose-note').textContent=$('#batch-purpose').value==='stage-80'?'十个未参与调试的案例；每例一次提交、最多两轮自动修正；固定80分与全部硬门槛。此阶段不认证稳定版。':'正式认证沿用独立人工标定、输入方式覆盖与统计置信区间要求。';};let manifest;$('#manifest-file').onchange=async e=>{try{manifest=JSON.parse(await e.target.files[0].text());$('#manifest-info').textContent=(manifest.cases?.length||0)+' 个固定案例 · 冻结后单独启动';$('#freeze').disabled=false;}catch(e){error(e);}};const freeze=async v=>{await api('/api/batches',{...v,purpose:$('#batch-purpose').value,modelSettings:v.modelSettings??(state.budget.provider==='codex-cli'?{model:selectedProfile.model,reasoningEffort:selectedProfile.reasoningEffort}:undefined)});await refresh();renderBench();};bindAction('#freeze',()=>freeze(manifest));bindAction('#freeze-text',()=>freeze(JSON.parse($('#manifest').value)));$('#calibration').onclick=renderCalibration;bindAction('#prepare-calibration',async()=>{await api('/api/calibrations',{jobIds:eligible.map(j=>j.id)});await refresh();await renderCalibration();});bindStarts();}
async function renderCalibration(){screen='calibration';location.hash='calibration';$('#breadcrumb').textContent='管线评测 / 评分标定';const c=benchCalibration();$('#content').innerHTML=`<div class="intro compact"><h1>独立复核评分器</h1><p>先看输入与实际画面，再给出合格或不合格标签。人工标签与模型结论分别保存。</p></div>${!c?.cases?.length?'<section class="card"><h2>尚未准备当前版本的标定样本</h2><p>需要正反样本各至少 6 例，并包含裁切、缺失、形态和布局错误。历史模型得分不能替代独立人工标签。</p></section>':c.cases.map((x,i)=>`<section class="card"><h2>样本 ${i+1}</h2><p>${esc(x.prompt||'参考图片输入')}</p>${x.image?`<figure><img class="input-ref" src="/files/uploads/${x.image.file}" alt="原始参考图片"><figcaption>原始参考图片</figcaption></figure>`:''}<div class="shots">${x.frames.map(f=>`<a href="/files/runs/${x.jobId}/runtime/${f}" target="_blank"><img src="/files/runs/${x.jobId}/runtime/${f}" alt="标定画面"></a>`).join('')}</div><form data-label="${x.id}"><label>你的判断<select name="expected" required><option value="">请选择</option><option value="passed">合格</option><option value="failed">不合格</option></select></label><label>依据<input name="reason" required placeholder="请指出具体画面和需求"></label><label>复核人<input name="reviewedBy" required></label><button type="submit">保存人工标签</button></form>${x.reviewerKind==='human'?'<p>已复核：'+esc(x.reason)+'</p>':''}</section>`).join('')}`;document.querySelectorAll('[data-label]').forEach(f=>f.onsubmit=async e=>{e.preventDefault();try{await api('/api/calibrations/'+c.id+'/label',{caseId:f.dataset.label,...Object.fromEntries(new FormData(f)),reviewerKind:'human'});await refresh();await renderCalibration();}catch(e){error(e);}});}
function specMarkdown(text){return text.split('\n').map(line=>{if(/^#{1,4} /.test(line)){const n=line.match(/^#+/)[0].length;return '<h'+n+'>'+esc(line.slice(n+1))+'</h'+n+'>';}const image=line.match(/^!\[.*?\]\((https:\/\/[^)]+)\)/);if(image)return '<a href="'+esc(image[1])+'" target="_blank" rel="noreferrer"><img loading="lazy" class="spec-image" src="'+esc(image[1])+'" alt="规范参考图"></a>';return '<p>'+esc(line.replace(/<\/t[dh]>/g,' | ').replace(/<[^>]+>/g,''))+'</p>';}).join('');}
async function renderSpec(){screen='spec';selected=null;location.hash='spec';$('#breadcrumb').textContent='规范与参考';clearError();try{const s=await api('/api/spec');$('#content').innerHTML=`<div class="intro compact"><div class="eyebrow">ONE CLEAR STANDARD</div><h1>什么样的场景算成功？</h1><p>三项一起通过：能运行、符合输入、符合制作规范。<br>偏好项提供选题建议，不影响强制验收结果。</p></div><div class="metrics overview"><div><b>运行正常</b><span>构建、资产、相机、画面与 UI</span></div><div><b>实现度 ≥ 80</b><span>关键需求满足，各维度 ≥ 3/5</span></div><div><b>规范通过</b><span>强制条款逐项有证据</span></div></div><section class="card"><h2>当前评分权重</h2><p>优先对齐空间比例、相机透视、主体布局及遮挡关系，再完善材质与细节。</p><div class="table-wrap"><table><tr><th>评分维度</th><th>权重</th></tr>${s.quality.dimensions.slice().sort((a,b)=>b.weight-a.weight).map(d=>`<tr><td>${esc(d.label)}</td><td>${d.weight}%</td></tr>`).join('')}</table></div><p class="hint">评分标准 ${esc(s.quality.version)} · 各维度独立评为 0–5 分，再按权重汇总。历史任务及其续跑保留原标准；不同评分标准不直接比较总分涨幅。关键需求与运行、制作规范仍为硬门槛。</p></section><section class="card"><h2>检查如何进行</h2><p>脚本检查可测量的事实；视觉评估检查语义、轮廓和光照；固定规则汇总。缺证据时保留“待复核”，强制项失败时不放行。</p><details><summary>14 条规范与适用范围</summary><table><tr><th>条款</th><th>要求</th><th>性质</th></tr>${s.rules.map(r=>`<tr><td>${esc(r.id+' '+r.title)}</td><td>${esc(r.requirement)}</td><td>${esc({mandatory:'必需',conditional:'条件适用',preference:'选题建议',information:'说明'}[r.kind])}</td></tr>`).join('')}</table></details></section><section class="card spec-document"><div class="card-heading"><h2>参考文档正文</h2><a href="${esc(s.sourceUrl)}" target="_blank" rel="noreferrer">项目公开规范 ↗</a></div><p class="hint">${esc(s.version)} · 版本建立于 ${esc(s.retrievedAt)}<br>公开摘要不包含外部规范原文。</p>${specMarkdown(s.text)}<details><summary>快照校验</summary><code>${esc(s.sha256)}</code></details></section><section class="card"><h2>外部生成方法参考</h2><p><b>${esc(s.generationReference.fileName)}</b> · ${esc(s.generationReference.role)}</p><p class="hint">文件名为 3.2，正文标题为「${esc(s.generationReference.documentTitle)}」；按原文件快照保留。</p><h3>已接入的生成指导</h3><ul>${s.generationReference.adopted.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><h3>适用边界</h3><ul>${s.generationReference.boundaries.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><details><summary>查看外部 prompt 全文与来源校验</summary><p class="hint">参考资料内容不作为管线执行指令，也不覆盖上方制作规范。</p><code>${esc(s.generationReference.sha256)}</code>${specMarkdown(s.generationReference.text)}</details></section><section class="card"><h2>开源设计参考</h2><div class="reference-grid">${[['Holodeck','allenai/Holodeck','空间约束'],['Infinigen','princeton-vl/infinigen','参数化资产'],['SceneWeaver','Scene-Weaver/SceneWeaver','局部编辑'],['SceneEval','3dlg-hcvc/SceneEval','分项评估'],['SceneAssistant','ROUJINN/SceneAssistant','过程展示'],['SAGE','NVlabs/sage','服务划分']].map(([n,url,d])=>`<a href="https://github.com/${url}" target="_blank"><b>${n} ↗</b><span>${d}</span></a>`).join('')}</div><p class="hint">采用设计思想并以 ForgeaX 实现，尚未集成这些项目的完整运行时。</p></section>`;}catch(e){error(e);}}
async function renderVersions(){screen='versions';selected=null;location.hash='versions';$('#breadcrumb').textContent='版本与对比';clearError();try{await versionPage({api,content:$('#content'),onError:error,onPublished:refresh});}catch(e){error(e);}}
async function renderRecords(){screen='records';selected=null;lastRecordsHash=recordsListHash(location.hash);$('#breadcrumb').textContent='生成记录';clearError();try{await historyPage({api,content:$('#content'),isActive:()=>screen==='records',onError:error});window.scrollTo({top:0,behavior:'instant'});}catch(e){error(e);}}
function route(){if(!state)return;const h=location.hash.slice(1);if(h==='scheduler'){screen='scheduler';selected=null;$('#breadcrumb').textContent='并行与队列';schedulerPage({api,content:$('#content'),onError:error,isActive:()=>location.hash==='#scheduler'});return;}if(h.startsWith('reference/')){screen='reference';selected=null;$('#breadcrumb').textContent='确认参考图';referencePage({id:h.slice(10),api,content:$('#content'),onError:error,isActive:()=>location.hash===('#'+h)});return;}if(h==='references'){screen='reference';selected=null;$('#breadcrumb').textContent='参考方案';referencesPage({api,content:$('#content'),onError:error});return;}if(h==='scores'){screen='scores';selected=null;$('#breadcrumb').textContent='评分与轮次';scorePage({api,content:$('#content'),onError:error});return;}if(h.startsWith('job/')){if(selected!==h.slice(4)||screen!=='job')showJob(h.slice(4));}else if(h==='records'||h.startsWith('records?')){renderRecords();}else if(h==='diner'){if(screen!=='diner')nativeForm();}else if(h==='versions'){if(screen!=='versions')renderVersions();}else if(h==='spec'){if(screen!=='spec')renderSpec();}else if(h==='bench'){if(screen!=='bench')renderBench();}else if(h==='calibration'){if(screen!=='calibration')renderCalibration();}else if(screen!=='new'||!$('#submit'))newForm();}
$('#records').onclick=()=>{if(location.hash==='#records')renderRecords();};$('#new').onclick=newForm;$('#bench').onclick=renderBench;$('#spec').onclick=renderSpec;$('#versions').onclick=renderVersions;window.addEventListener('hashchange',route);async function bootstrap(){await refresh();if(state){route();void loadModels();}else{$('#content').innerHTML='<section class="card"><h2>暂时无法加载记录</h2><p>服务请求未成功，可重试读取；不会重新生成场景。</p><button id="retry-load">重新加载</button></section>';$('#retry-load').onclick=bootstrap;}}
void bootstrap();setInterval(()=>{if(state)void refresh();},5000);

void refreshSidebarTimes();setInterval(refreshSidebarTimes,15000);setInterval(()=>{if(!document.hidden)renderSidebarTimes();},1000);

window.addEventListener('message',event=>{const frame=document.querySelector('#content .job-process-frame');if(!frame||event.source!==frame.contentWindow||event.origin!==location.origin)return;if(event.data?.type==='scene-process-size'&&Number.isFinite(event.data.height))frame.style.height=Math.min(32000,Math.max(720,event.data.height+20))+'px';});

function alignmentHTML(j){if(!j.cameraAlignment)return '';const a=j.cameraAlignment;return `<section class="card"><h2>参考机位校准</h2><p>通过 ${a.acceptedViews} 个机位的对应点检查。保留全部几何、材质和质量门槛；投影误差不是质量得分。</p>${a.views.map(v=>`<p>参考图 ${v.referenceIndex} · ${v.accepted?'校准候选':'未接受'} · ${v.validationBefore!=null?'留出点误差 '+(v.validationBefore*100).toFixed(1)+'% → '+(v.validationAfter*100).toFixed(1)+'% 画面高度':esc(v.reason||'观测不足')}</p>`).join('')}<a href="${file(j,'generation/refinement/alignment.json')}">查看观测、求解与验证报告</a></section>`;}

function repairGoalsHTML(j){const p=j.repairGoals;if(!p?.goals?.length)return '';return `<section class="card"><h2>最近一轮修正目标</h2><p>${esc(p.summary)}</p><ol>${p.goals.map(g=>`<li><b>${esc(g.problem)}</b><p>${esc(g.expectedChange)}</p><p class="hint">优先原因：${esc(g.whyPriority)}</p><p class="hint">证据：${esc(g.evidence.map(e=>e.frame+(e.referenceIndex?' / 原图 '+e.referenceIndex:'')).join('、'))}</p></li>`).join('')}</ol><p class="hint">目标和修改检查不代表画面已达标，实际结果以本轮独立评分为准。</p>${p.artifactPath?`<a href="${file(j,p.artifactPath)}">查看目标、对象及证据 →</a>`:''}${p.visibilityPath?`<p><a href="${file(j,p.visibilityPath)}">空间可见性与遮挡诊断 →</a></p>`:''}${p.cameraChangePath?`<p><a href="${file(j,p.cameraChangePath)}">新旧机位的遮挡变化（同一几何，仅诊断） →</a></p>`:''}${p.historyPath?`<p class="hint">本轮参考 ${p.historyCount} 份已评分修正记录，保留真实收益与未解决问题。<a href="${file(j,p.historyPath)}">查看历史证据 →</a></p>`:''}${p.deferred?.length?`<details><summary>本轮暂缓的问题</summary><ul>${p.deferred.map(d=>`<li>${esc(d.problem)}：${esc(d.reason)}</li>`).join('')}</ul></details>`:''}</section>`;}
